#!/usr/bin/env bash
# Compiles Shared/Core + the pure test files with swiftc and runs them on Linux, without Xcode or the SDK.
# XCTest is replaced by scripts/linux/XCTestShim.swift and a generated main (scripts/linux_alltests.py).
# On a Mac, Cmd-U runs the same files (plus the Mac-only NotesCryptoTests and AuthTests) under real XCTest.
#   SRC_DIR   alternative Shared/Core (a mutation harness can point it at a mutant copy)
#   OUT       build folder (default /tmp/liamac-core-tests)
set -euo pipefail
cd "$(dirname "$0")/.."
OUT="${OUT:-/tmp/liamac-core-tests}"
SRC="${SRC_DIR:-Shared/Core}"
TESTS=(Tests/CoreTests.swift Tests/LiaStateTests.swift Tests/ModesTests.swift Tests/PlanTests.swift Tests/BillingTests.swift Tests/MemoryTests.swift Tests/QuizTests.swift Tests/AdScreensTests.swift Tests/CheckoutUsageTests.swift Tests/EntityChipsTests.swift Tests/RelayLookTests.swift Tests/ReviewFixesTests.swift Tests/AgentTraceTests.swift Tests/WebAgentCoreTests.swift Tests/AgentsCoreTests.swift Tests/SuggestTests.swift Tests/DialoguesTests.swift Tests/PanelProfilesTests.swift Tests/OmniEntitiesTests.swift Tests/GoogleAccountsTests.swift Tests/ChromiumImportTests.swift Tests/AgentHistoryTests.swift Tests/DevAgentTests.swift Tests/CanvasTests.swift Tests/GitHubTests.swift Tests/SkyTests.swift Tests/AgentItemsTests.swift Tests/TabStripTests.swift Tests/TabFitTests.swift Tests/DevWorkTests.swift Tests/HomeCoreTests.swift Tests/DevArtTests.swift Tests/DevCloudTests.swift Tests/DevReposTests.swift Tests/TableFitTests.swift Tests/CreaTests.swift Tests/CreaLayersTests.swift Tests/CreaRegionTests.swift Tests/CreaStudioTests.swift Tests/CreaPlaceTests.swift Tests/SkyFadeTests.swift Tests/LoadFailureTests.swift Tests/UpdatePolicyTests.swift Tests/AgentActivityTests.swift Tests/HomeInkTourTests.swift Tests/HeroMovesTests.swift Tests/QRSignInTests.swift Tests/PasswordTests.swift Tests/AppleSignInTests.swift Tests/MacSignInTests.swift Tests/GoogleSignInTests.swift Tests/GoogleSignInLiveKeyTests.swift Tests/BrandMarksTests.swift Tests/NotesSyncTests.swift Tests/RosterCacheTests.swift Tests/ReloadPolicyTests.swift Tests/ClientHeaderTests.swift Tests/ClicksTests.swift Tests/TourGeometryTests.swift Tests/LatencyTests.swift Tests/LatencyEventsTests.swift Tests/ScreenTimeTests.swift Tests/TabRestoreTests.swift Tests/DevPickerTests.swift Tests/EmojiIconsTests.swift Tests/BriefPeriodTests.swift Tests/ScreenShareTests.swift Tests/ScreenshotWatchTests.swift Tests/PageTranslateTests.swift Tests/AgentWaitPolicyTests.swift Tests/AuthNoWebTests.swift Tests/UploadsTests.swift Tests/WebPanelRulesTests.swift Tests/SignInCookiesTests.swift Tests/AgentAttentionTests.swift Tests/DevLinksChipsTests.swift Tests/LoadFailLogTests.swift Tests/CodeViewerTests.swift Tests/LiaContextTests.swift Tests/GitHubEntityChipsTests.swift Tests/FileChipsTests.swift Tests/VoiceChunkerTests.swift Tests/PaneFoldTests.swift Tests/AgentChipsTests.swift Tests/PhotoFanTests.swift Tests/AvatarsTests.swift Tests/GoogleListPostTests.swift Tests/LocalFileOpenTests.swift Tests/CreatorCodeTests.swift Tests/AboutYouTests.swift)
rm -rf "$OUT" && mkdir -p "$OUT"
for f in "${TESTS[@]}"; do sed -e '/^import XCTest$/d' -e '/^@testable import/d' "$f" > "$OUT/$(basename "$f")"; done
python3 scripts/linux_alltests.py "${TESTS[@]}" > "$OUT/main.swift"
${SWIFTC:-swiftc} -suppress-warnings -o "$OUT/run" "$SRC"/*.swift Shared/Icons/LiaIconData.swift scripts/linux/XCTestShim.swift "$OUT"/*Tests.swift "$OUT/main.swift"
"$OUT/run"
